1449	func scoreRecord(record MemoryRecord, primaryOverlap int, now time.Time) int {
1450		if primaryOverlap == 0 {
1451			return 0
1452		}
1453	
1454		score := primaryOverlap * 7
1455		switch record.Kind {
1456		case KindRepoRule, KindAgentInstruction:
1457			score += 15
1458		case KindSkillPatch:
1459			score += 4
1460		case KindWorkflowRule, KindAntiPattern, "":
1461		}
1462		score += minInt(record.Strength, 5)
1463	
1464		if !record.UpdatedAt.IsZero() && now.After(record.UpdatedAt) {
1465			age := now.Sub(record.UpdatedAt)
1466			if age <= 14*24*time.Hour {
1467				score += 2
1468			}
1469		}
1470	
1471		return score
1472	}
