212			}
213			if isLiteralReviewEvidence(record, input.Analysis.ReviewDerivedRules) {
214				stats.FilteredGenericCount++
215				continue
216			}
217			if !passesEvidenceGate(record, item.SourceSignal, input.Analysis, validSourceIDs) {
218				stats.FilteredNoEvidenceCount++
219				continue
220			}
221	
222			key := normalizedGeneratedCandidateKey(kind, title, body)
223			next := generatedCandidate{
224				record:            record,
225				confidenceRank:    confidenceRank(confidence),
226				specificityScore:  generatedSpecificityScore(title, body),
227				normalizedContent: len(normalizeGeneratedText(title)) + len(normalizeGeneratedText(body)),
228			}
229			existing, ok := bestByKey[key]
230			if !ok {
231				orderedKeys = append(orderedKeys, key)
232				bestByKey[key] = next
233				continue
234			}
235			stats.DedupedCount++
236			if shouldReplaceGeneratedCandidate(existing, next) {
