238			}
239		}
240	
241		records := make([]MemoryRecord, 0, len(orderedKeys))
242		for _, key := range orderedKeys {
243			records = append(records, bestByKey[key].record)
244			if len(records) >= input.MaxRecords {
245				break
246			}
247		}
248	
249		return records, stats
250	}
