27	func (m settingsModel) update(msg tea.Msg) (settingsModel, tea.Cmd) {
28		if m.state == nil || m.state.Store == nil {
29			return m, nil
30		}
31	
32		keyMsg, ok := msg.(tea.KeyMsg)
33		if !ok {
34			return m, nil
35		}
36	
37		var changed settingsChangedMsg
38		hasChange := false
39	
40		switch {
41		case key.Matches(keyMsg, settingsKeyMap.Mode):
42			next := cycleMode(m.state.Store.Mode)
43			changed.mode = &next
44			hasChange = true
45	
46		case key.Matches(keyMsg, settingsKeyMap.Policy):
47			next := cyclePolicy(m.state.Store.ActivationPolicy)
48			changed.activationPolicy = &next
49			hasChange = true
50	
51		case key.Matches(keyMsg, settingsKeyMap.MaxUp):
52			next := m.state.Store.MaxInjected + 1
53			if next > 10 {
54				next = 10
55			}
56			changed.maxInjected = &next
57			hasChange = true
58	
59		case key.Matches(keyMsg, settingsKeyMap.MaxDown):
60			next := m.state.Store.MaxInjected - 1
61			if next < 1 {
62				next = 1
63			}
64			changed.maxInjected = &next
65			hasChange = true
66	
67		case key.Matches(keyMsg, settingsKeyMap.ScopeRepo):
68			scopes := toggleScope(m.state.Store.InjectionScopes, memoryloop.ScopeKindRepo)
69			changed.injectionScopes = &scopes
70			hasChange = true
71	
72		case key.Matches(keyMsg, settingsKeyMap.ScopeMe):
73			scopes := toggleScope(m.state.Store.InjectionScopes, memoryloop.ScopeKindMe)
74			changed.injectionScopes = &scopes
75			hasChange = true
76	
77		case key.Matches(keyMsg, settingsKeyMap.ScopeBranch):
78			scopes := toggleScope(m.state.Store.InjectionScopes, memoryloop.ScopeKindBranch)
79			changed.injectionScopes = &scopes
80			hasChange = true
81		}
82	
83		if hasChange {
84			return m, func() tea.Msg { return changed }
85		}
86		return m, nil
87	}
